const fs = require('fs');

// Свежий endpoints.json = база (там runId)
const epFiles = fs.readdirSync('/results')
  .filter(f => f.endsWith('_endpoints.json'))
  .map(f => ({ name: f, mtime: fs.statSync(`/results/${f}`).mtime.getTime() }))
  .sort((a, b) => b.mtime - a.mtime);

if (epFiles.length === 0) throw new Error('No endpoints.json');

const discovery = JSON.parse(fs.readFileSync(`/results/${epFiles[0].name}`, 'utf8'));
const runId = discovery.runId;
const startTime = discovery.startTime; 

console.log('Loading runId:', runId);

// Читаем 3 файла
let dictData = { ffuf: { results: [] }, wfuzz: { results: [] } };
let schemaData = { schemathesis: { results: [], stats: {} }, cats: { results: [], stats: {} } };
let baseline = {};

try {
  dictData = JSON.parse(fs.readFileSync(discovery.dictResultsFile, 'utf8'));
  console.log(`Dict: ffuf=${dictData.ffuf?.results?.length || 0}, wfuzz=${dictData.wfuzz?.results?.length || 0}`);
} catch (e) { console.error('dict read error:', e.message); }

try {
  schemaData = JSON.parse(fs.readFileSync(discovery.schemaResultsFile, 'utf8'));
  console.log(`Schema: schemathesis=${schemaData.schemathesis?.results?.length || 0}, cats=${schemaData.cats?.results?.length || 0}`);
} catch (e) { console.error('schema read error:', e.message); }

try {
  baseline = JSON.parse(fs.readFileSync(discovery.baselineFile, 'utf8'));
  console.log(`Baseline: ${baseline.status} / ${baseline.length}`);
} catch (e) { console.error('baseline read error:', e.message); }

// === НОВОЕ: Nuclei ===
let nucleiData = { nuclei: { results: [], stats: { total: 0, bySeverity: {} } } };

try {
  const nucleiFile = `/results/${runId}_nuclei_results.json`;
  if (fs.existsSync(nucleiFile)) {
    nucleiData = JSON.parse(fs.readFileSync(nucleiFile, 'utf8'));
    console.log(`Nuclei: ${nucleiData.nuclei?.results?.length || 0} findings`);
  } else {
    console.log(`Nuclei file not found: ${nucleiFile}`);
  }
} catch (e) {
  console.error('nuclei read error:', e.message);
}

return [{ json: {
  ...discovery,
  dictData,
  schemaData,
  baseline,
  nucleiData, 
  startTime,// ← НОВОЕ
}}];

const cfg = $input.first().json;

const ffufResults  = cfg.dictData?.ffuf?.results  || [];
const wfuzzResults = cfg.dictData?.wfuzz?.results || [];
const schemaResults = cfg.schemaData?.schemathesis?.results || [];
const catsResults   = cfg.schemaData?.cats?.results || [];

const baseline = cfg.baseline?.length || 0;
const baselineStatus = cfg.baseline?.status || 200;

console.log(`Analyze: ffuf=${ffufResults.length}, wfuzz=${wfuzzResults.length}, schema=${schemaResults.length}, cats=${catsResults.length}, baseline=${baseline}`);

// === ФИЛЬТР АНОМАЛИЙ для ffuf/wfuzz ===
function isDictAnomaly(r) {
  if (r.status >= 500) return true;
  if (r.status === 403 || r.status === 401) return true;
  if (r.status === 301 || r.status === 302) return true;
  if (r.status >= 400 && r.status < 500) return true;
  if (r.status === 200 && baseline > 0) {
    const diff = Math.abs(r.length - baseline);
    if (diff > baseline * 0.3) return true;
  }
  if (r.time_ms > 2000) return true;
  return false;
}

const allDict = [...ffufResults, ...wfuzzResults];
const dictAnomalies = allDict.filter(isDictAnomaly);

// Группировка
const grouped = {};
for (const a of dictAnomalies) {
  const key = `${a.endpoint}?${a.param}`;
  if (!grouped[key]) grouped[key] = [];
  grouped[key].push(a);
}

// Status breakdown
const statusBreakdown = {};
for (const r of allDict) {
  statusBreakdown[r.status] = (statusBreakdown[r.status] || 0) + 1;
}

// Anomalies by status
const anomaliesByStatus = {};
for (const a of dictAnomalies) {
  anomaliesByStatus[a.status] = (anomaliesByStatus[a.status] || 0) + 1;
}

// Топ-40 с распределением по инструментам
const byTool = { ffuf: [], wfuzz: [] };
for (const a of dictAnomalies) {
  if (byTool[a.tool]) byTool[a.tool].push(a);
}
const perTool = 20;
const topAnomalies = [
  ...byTool.ffuf.slice(0, perTool),
  ...byTool.wfuzz.slice(0, perTool),
].slice(0, 40);

// Уникальные endpoints/params
const endpointsSet = new Set(allDict.map(r => r.endpoint));
const paramsSet = new Set(allDict.map(r => r.param));

// === ИТОГ ===
const analysis = {
  runId: cfg.runId,
  target: cfg.target,
  vulnType: cfg.vulnType,
  owaspCategory: cfg.owaspCategory,
  owaspName: cfg.owaspName,
  wordlist: cfg.wordlist,
  useArjun: cfg.dictData?.useArjun || false,
  arjunStatus: cfg.dictData?.arjunStatus || 'unknown',
  reportOut: cfg.reportFile,
  timestamp: new Date().toISOString(),

  baseline,
  baselineStatus,
  baselineUrl: cfg.baselineUrl,

  totalRequests: allDict.length,
  totalAnomalies: dictAnomalies.length,
  anomaliesByStatus,

  endpointsTested: endpointsSet.size,
  paramsTested: paramsSet.size,
  statusBreakdown,

  tools: {
    ffuf:  { total: ffufResults.length,  anomalies: dictAnomalies.filter(a => a.tool === 'ffuf').length },
    wfuzz: { total: wfuzzResults.length, anomalies: dictAnomalies.filter(a => a.tool === 'wfuzz').length },
    schemathesis: {
      total:    schemaResults.length,
      failures: cfg.schemaData?.schemathesis?.stats?.failures || 0,
      errors:   cfg.schemaData?.schemathesis?.stats?.errors   || 0,
      skipped:  cfg.schemaData?.schemathesis?.stats?.skipped  || 0,
    },
    cats: (() => {
      const c = cfg.schemaData?.cats || {};
      const results = c.results || [];
      const stats = c.stats || {};
      return {
        total:    stats.total    || results.length,
        failures: stats.failures || results.filter(r => r.isFailure).length,
        errors:   stats.errors   || results.filter(r => r.isError).length,
        skipped:  stats.skipped  || 0,
      };
    })(),
    nuclei: {
      total: cfg.nucleiData?.nuclei?.results?.length || 0,
      findings: cfg.nucleiData?.nuclei?.results?.length || 0,
      bySeverity: cfg.nucleiData?.nuclei?.stats?.bySeverity || {},
    },
  },

  topAnomalies,
  groupedByEndpoint: grouped,
  schemathesisFindings: schemaResults.slice(0, 30),
  catsFindings: catsResults.slice(0, 50),
};

console.log(`Analysis: totalRequests=${analysis.totalRequests}, anomalies=${analysis.totalAnomalies}, endpoints=${analysis.endpointsTested}`);

// === МЕТРИКИ (для диплома) ===
const metrics = {
  totalDurationSec: cfg.startTime
    ? round((Date.now() - cfg.startTime) / 1000, 2)
    : null,
  requestsPerSec: null,
  findingRate: allDict.length > 0
    ? round(dictAnomalies.length / allDict.length, 4)
    : 0,
  totalFindings: dictAnomalies.length
    + (cfg.nucleiData?.nuclei?.results?.length || 0)
    + (schemaResults.length || 0)
    + (catsResults.length || 0),
  owaspCoverage: 0,
};

if (metrics.totalDurationSec && metrics.totalDurationSec > 0) {
  metrics.requestsPerSec = round(allDict.length / metrics.totalDurationSec, 1);
}

const owaspSet = new Set();
if (cfg.owaspCategory) owaspSet.add(cfg.owaspCategory);
for (const f of (cfg.nucleiData?.nuclei?.results || [])) {
  for (const tag of (f.owaspTags || [])) owaspSet.add(tag);
}
metrics.owaspCoverage = owaspSet.size;

function round(n, d) {
  return Math.round(n * Math.pow(10, d)) / Math.pow(10, d);
}

console.log(`Metrics: duration=${metrics.totalDurationSec}s, rps=${metrics.requestsPerSec}, findings=${metrics.totalFindings}, owasp=${metrics.owaspCoverage}/10`);

analysis.metrics = metrics;

return [{ json: analysis }];

const report = $input.first().json;
const fs = require('fs');

try {
  fs.writeFileSync(report.reportOut, JSON.stringify(report, null, 2));
  console.log(`Workflow 5 DONE. Report: ${report.reportOut}`);
  console.log(`  Total requests: ${report.totalRequests}`);
  console.log(`  Anomalies: ${report.totalAnomalies}`);
  console.log(`  Endpoints: ${report.endpointsTested}`);
  console.log(`  Tools: ffuf=${report.tools.ffuf.total}, wfuzz=${report.tools.wfuzz.total}, schemathesis=${report.tools.schemathesis.total}, cats=${report.tools.cats.total}`);
} catch (e) {
  console.error('Write failed:', e.message);
}

require('fs').writeFileSync('/results/status.json', JSON.stringify({ status: 'FINISHED', target: report.target }));

return [{ json: report }];

// Берём отчёт из узла Write Report — там все findings
const report = $('Write Report').first().json;

const findings = [];

// === 1. Аномалии от ffuf/wfuzz ===
// groupedByEndpoint: { "endpoint?param": [ {tool, endpoint, param, payload, status, ...}, ... ] }
// === 1. Аномалии от ffuf/wfuzz — по 50 от каждого ===
const dictAnoms = report.groupedByEndpoint
  ? Object.values(report.groupedByEndpoint).flat()
  : [];

// Разделяем по инструментам
const ffufAnoms = dictAnoms.filter(f => f.tool === 'ffuf').slice(0, 50);
const wfuzzAnoms = dictAnoms.filter(f => f.tool === 'wfuzz').slice(0, 50);

for (const f of [...ffufAnoms, ...wfuzzAnoms]) {
  findings.push({
    runId: report.runId,
    target: report.target,
    vulnType: report.vulnType,
    owaspCategory: report.owaspCategory,
    tool: f.tool,
    endpoint: f.endpoint,
    param: f.param,
    payload: f.payload,
    status: f.status,
    length: f.length,
    time_ms: f.time_ms,
    timestamp: new Date(),
  });
}

// === 2. Schemathesis findings ===
for (const f of (report.schemathesisFindings || [])) {
  findings.push({
    runId: report.runId,
    target: report.target,
    vulnType: report.vulnType,
    owaspCategory: report.owaspCategory,
    tool: 'schemathesis',
    method: f.method,
    endpoint: f.endpoint,
    payload: f.payload,
    message: f.message,
    isFailure: f.isFailure,
    isError: f.isError,
    timestamp: new Date(),
  });
}

// === 3. CATS findings ===
for (const f of (report.catsFindings || [])) {
  findings.push({
    runId: report.runId,
    target: report.target,
    vulnType: report.vulnType,
    tool: 'cats',
    endpoint: f.endpoint,
    payload: f.payload,
    message: f.message,
    isFailure: f.isFailure,
    isError: f.isError,
    timestamp: new Date(),
  });
}

// === 4. Nuclei findings ===
for (const f of (report.nucleiData?.nuclei?.results || [])) {
  findings.push({
    runId: report.runId,
    target: report.target,
    vulnType: report.vulnType,
    owaspCategory: f.owaspTags?.[0] || report.owaspCategory || '',
    tool: 'nuclei',
    endpoint: f.endpoint || '',
    payload: f.payload || '',
    severity: f.severity || 'unknown',
    templateId: f.templateId || '',
    templateName: f.templateName || '',
    message: f.message || '',
    isFailure: true,
    timestamp: new Date(),
  });
}

console.log(`Prepared ${findings.length} findings for MongoDB`);
console.log(`  dict (ffuf+wfuzz): ${dictAnoms.length} (top-500)`);
console.log(`  schemathesis: ${(report.schemathesisFindings || []).length}`);
console.log(`  cats: ${(report.catsFindings || []).length}`);
console.log(`Nuclei findings pushed: ${(report.nucleiData?.nuclei?.results || []).length}`);

return findings.map(f => ({ json: f }));
